param([Parameter(Mandatory=$true)][string]$GatePath)
$ErrorActionPreference='Stop';$g=Get-Content -LiteralPath (Resolve-Path -LiteralPath $GatePath) -Raw|ConvertFrom-Json
if($g.schema_version-ne1-or$g.artifact_type-ne'r15_canonical_launch_gate'-or$g.status-ne'pass'-or$g.fresh_launch_authorized-ne$true-or$g.run_id_prefix-ne'paper-text-v1-multiseed-cap128-r15-20260831'-or(@($g.seeds)-join'|')-ne'42|43'){throw 'r15 gate identity/status failed'}
if($g.protocol.stage3_stability_adaptation_id-ne'PAPER_TEXT_STAGE3_GLOBAL_NORM_CLIP_V1'-or[double]$g.protocol.stage3_gradient_clip_norm-ne1.0-or[int]$g.protocol.stage3_gradient_accumulation_steps-ne128-or$g.protocol.stage3_gradient_clip_application_point-ne'after_effective_batch_average_before_optimizer_step'){throw 'r15 scientific protocol gate failed'}
if([int]$g.durable_supervisor.pre_attempt_deadline_seconds-ne120-or$g.durable_supervisor.wmi_forbidden-ne$true-or$g.durable_supervisor.cim_forbidden-ne$true-or$g.durable_supervisor.runtime_add_type_forbidden-ne$true-or$g.durable_supervisor.native_storage-ne$true){throw 'r15 durable supervisor gate failed'}
if($g.review.status-ne'pass'-or$g.review.no_material_finding-ne$true-or[string]$g.review.reviewer_thread_id-notmatch'^[0-9a-f-]{36}$'){throw 'r15 independent review gate failed'}
$seen=@{};foreach($b in @($g.source_bindings)){if($seen.ContainsKey([string]$b.name)){throw 'duplicate gate source binding'};$p=(Resolve-Path -LiteralPath ([string]$b.path)).Path;if((Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()-ne[string]$b.sha256){throw "gate source changed: $($b.name)"};$seen[[string]$b.name]=$true};foreach($n in @('dispatcher_ps1','supervisor_ps1','supervisor_template_ps1','foreground_wrapper_sh','r15_exactly_once_helpers_ps1','r15_native_probe_cs','r15_native_probe_dll','r15_confirmation_builder_ps1','r15_confirmation_refusal_smoke_ps1')){if(!$seen.ContainsKey($n)){throw "required gate source absent: $n"}}
[ordered]@{status='pass';fresh_launch_authorized=$true;source_bindings=$seen.Count;reviewer_thread_id=[string]$g.review.reviewer_thread_id}|ConvertTo-Json -Compress
